"""Generates a standalone Python script that runs an automation."""

from __future__ import annotations

import json
import os
from pathlib import Path

from guiautomation.model import Automation, automation_to_dict

DEFAULT_EXPORT_DELAY = 5.0

_TEMPLATE = """\
# Generated by guiautomation. Requires the guiautomation package to be installed.
# Image paths in the steps are relative to this folder, so keep it in place:
# {base_dir}
import argparse
import json
import sys
from pathlib import Path

from guiautomation.cli import make_output_safe
from guiautomation.model import ValidationError, automation_from_dict
from guiautomation.runner import EXIT_ABORTED, EXIT_BAD_INPUT, exit_code_for, run_automation

AUTOMATION_JSON = {automation_json}
DELAY_SECONDS = {delay}


def parse_delay(argv: list[str] | None) -> float:
    parser = argparse.ArgumentParser(description="Run this exported test.")
    group = parser.add_mutually_exclusive_group()
    group.add_argument("--no-delay", action="store_true", help="start immediately")
    group.add_argument("--delay", type=float, metavar="N", help="seconds to wait before starting")
    args = parser.parse_args(argv)
    if args.no_delay:
        return 0.0
    return DELAY_SECONDS if args.delay is None else args.delay


def main(argv: list[str] | None = None) -> int:
    make_output_safe()
    delay = parse_delay(argv)
    base_dir = {base_dir}
    try:
        automation = automation_from_dict(json.loads(AUTOMATION_JSON), base_dir)
        result = run_automation(automation, delay=delay)
    except ValidationError as exc:
        print(f"error: {{exc}}", file=sys.stderr)
        return EXIT_BAD_INPUT
    except KeyboardInterrupt:
        print("Aborted.", file=sys.stderr)
        return EXIT_ABORTED
    print(result.summary())
    return exit_code_for(result)


if __name__ == "__main__":
    sys.exit(main())
"""


def _base_dir_expression(automation: Automation, script_path: Path | None) -> str:
    here = "Path(__file__).resolve().parent"
    if automation.base_dir is None or script_path is None:
        return here
    base = automation.base_dir.resolve()
    try:
        relative = os.path.relpath(base, script_path.resolve().parent)
    except ValueError:  # Different drives on Windows
        return f"Path({str(base)!r})"
    return f"({here} / {relative!r}).resolve()"


def render_script(
    automation: Automation,
    script_path: Path | None = None,
    delay: float = DEFAULT_EXPORT_DELAY,
) -> str:
    """Return the script's source. All values are embedded with repr of JSON text."""
    payload = json.dumps(automation_to_dict(automation))
    return _TEMPLATE.format(
        automation_json=repr(payload),
        delay=repr(float(delay)),
        base_dir=_base_dir_expression(automation, script_path),
    )


def export_script(automation: Automation, script_path: str | os.PathLike[str]) -> Path:
    """Write the generated script and return its path."""
    path = Path(script_path)
    path.write_text(render_script(automation, path), encoding="utf-8")
    return path
